import app from 'flarum/admin/app';
import { NS } from '../../common/levels';
export const KEY = 'ernestdefoe-trust-levels.config';
export const t = (key, params = {}) => app.translator.trans(`${NS}.admin.${key}`, params);
/** Which requirements each automatic level has (the columns of the grid). */
export const REQS = {
  1: ['topics_entered', 'posts_read', 'read_minutes'],
  2: ['days_visited', 'topics_entered', 'posts_read', 'read_minutes', 'replied_topics', 'likes_given', 'likes_received'],
  3: ['days_visited', 'replied_topics', 'topics_percent', 'topics_max', 'posts_percent', 'posts_max', 'likes_given', 'likes_received', 'likes_received_users', 'likes_received_days', 'flagged_posts', 'flagged_by', 'suspended_months']
};

/** The rows of the requirement grid, in order. */
export const REQ_ROWS = ['days_visited', 'topics_entered', 'posts_read', 'read_minutes', 'replied_topics', 'likes_given', 'likes_received', 'likes_received_users', 'likes_received_days', 'topics_percent', 'topics_max', 'posts_percent', 'posts_max', 'flagged_posts', 'flagged_by', 'suspended_months'];

/** Requirements and limits that only count while another extension is on. */
export const NEEDS = {
  likes_given: 'flarum-likes',
  likes_received: 'flarum-likes',
  likes_received_users: 'flarum-likes',
  likes_received_days: 'flarum-likes',
  flagged_posts: 'flarum-flags',
  flagged_by: 'flarum-flags',
  mentions: 'flarum-mentions',
  messages_day: 'flarum-messages'
};

/** The server's defaults (Config::DEFAULTS), sent with the admin page. */

export const defaults = () => app.data.trustLevelDefaults;
export function enabled(id) {
  try {
    return JSON.parse(app.data.settings.extensions_enabled || '[]').includes(id);
  } catch (e) {
    // Unreadable list: show the extension as off rather than break the page.
    return false;
  }
}
flarum.reg.add('ernestdefoe-trust-levels', 'admin/components/shared', { KEY: KEY,t: t,REQS: REQS,REQ_ROWS: REQ_ROWS,NEEDS: NEEDS,defaults: defaults,enabled: enabled, });